// The chart and the drawing. Lanes are keys; see main.js.
var LANES = [
  { does: 'left', peep: 'peepz/bunny', hue: 190 },
  { does: 'mid', peep: 'peepz/cat', hue: 322 },
  { does: 'right', peep: 'peepz/chick', hue: 48 },
]
var STEP = 500        // ms per chart step
var DROP = 2000       // a note is visible this long before its moment
var PATTERN = [0, -1, 1, -1, 2, 0, -1, 1, 2, -1, 0, 1, -1, 2, 1, 0,
               0, 1, -1, 2, -1, 1, 0, -1, 2, 2, -1, 0, 1, -1, 2, -1]

// Every note is fully described by its index: the chart is the code, so
// every player is playing the same song without a byte on the wire.
function noteAt(step) {
  var lane = PATTERN[step % PATTERN.length]
  return lane === -1 ? null : lane
}

function laneX(lane) {
  return width / 2 + (lane - 1) * min(140, width / 4)
}

function drawLane(lane, faces) {
  var x = laneX(lane)
  colorMode(HSB, 360, 100, 100)
  stroke(LANES[lane].hue, 40, 60)
  strokeWeight(1)
  line(x, 0, x, height)
  noFill()
  stroke(LANES[lane].hue, 70, 95)
  strokeWeight(3)
  circle(x, height - 140, 84)
  colorMode(RGB, 255)
  noStroke()
  var face = faces[lane]
  if (face.ready) image(face.image, x - 24, height - 120, 48, 48)
}

function drawNote(lane, msLeft, faces) {
  var x = laneX(lane)
  var y = map(msLeft, DROP, 0, -60, height - 140)
  var face = faces[lane]
  if (face.ready) image(face.image, x - 30, y - 30, 60, 60)
  else { noStroke(); fill(255); circle(x, y, 40) }
}

function drawScores() {
  noStroke()
  textAlign(LEFT)
  textSize(14)
  var top = xp.players.slice().sort(function (a, b) {
    return (b.avatar.data.score || 0) - (a.avatar.data.score || 0)
  })
  for (var i = 0; i < top.length && i < 6; i += 1) {
    fill(top[i].you ? color(160, 235, 255) : color(255, 255, 255, 170))
    text(top[i].name + '  ' + (top[i].avatar.data.score || 0), 16, 28 + i * 22)
  }
}

