// Peep Beat: notes fall down three lanes, each lane is a key
// (and a button on a phone). Hit the ring on the beat. Everybody plays
// the same chart; scores ride the avatar sync, so the board is live.
var faces = []
var judged = {}       // note step -> true once scored or missed
var said = ''         // the last verdict, drawn big for a moment
var saidAt = -9999

function setup() {
  createCanvas(windowWidth, windowHeight)
  for (var i = 0; i < LANES.length; i += 1) faces.push(xp.load.image(LANES[i].peep))
  xp.avatar.data.score = 0
  xp.avatar.data.streak = 0

  xp.on('press', function (name, p) {
    if (!p.you) return
    for (var lane = 0; lane < LANES.length; lane += 1) {
      if (LANES[lane].does === name) judge(lane)
    }
  })
}

function windowResized() { resizeCanvas(windowWidth, windowHeight) }

function judge(lane) {
  var now = millis()
  var best = null, bestOff = 99999
  // The nearest unjudged note in this lane, within reach.
  for (var step = floor((now - DROP) / STEP); step <= ceil((now + 300) / STEP); step += 1) {
    if (step < 0 || judged[step] || noteAt(step) !== lane) continue
    var off = now - step * STEP
    if (abs(off) < abs(bestOff)) { best = step; bestOff = off }
  }
  if (best === null || abs(bestOff) > 200) return
  judged[best] = true
  if (abs(bestOff) < 70) {
    xp.avatar.data.streak += 1
    xp.avatar.data.score += 3 + xp.avatar.data.streak
    say('perfect')
    // A sound made, not loaded: the pitch climbs with the streak, which no
    // recorded take could do.
    xp.tone(520 + min(xp.avatar.data.streak, 20) * 24, 0.12, 'triangle')
  } else {
    xp.avatar.data.streak = 0
    xp.avatar.data.score += 1
    say('good')
    xp.tone(360, 0.1, 'sine')
  }
}

function say(what) { said = what; saidAt = millis() }

function draw() {
  background(6, 2, 20)
  var now = millis()

  for (var lane = 0; lane < LANES.length; lane += 1) drawLane(lane, faces)

  // Every note whose moment is near, drawn falling; a missed one resets
  // the streak exactly once as it slips past the ring.
  for (var step = floor((now - 400) / STEP); step <= ceil((now + DROP) / STEP); step += 1) {
    if (step < 0) continue
    var lane = noteAt(step)
    if (lane === null) continue
    var msLeft = step * STEP - now
    if (msLeft < -200) {
      if (!judged[step]) { judged[step] = true; xp.avatar.data.streak = 0; say('miss'); xp.tone(140, 0.2, 'sawtooth') }
      continue
    }
    if (!judged[step]) drawNote(lane, msLeft, faces)
  }

  if (now - saidAt < 500) {
    textAlign(CENTER)
    textSize(28)
    fill(said === 'miss' ? color(255, 120, 140) : color(160, 235, 255))
    text(said, width / 2, height - 200)
  }

  drawScores()
}
